export function connectOctober13FinanceGuides(post) {
  const connection = inboundLinks[post.slug];
  if (!connection) return post;
  const [heading,content] = connection;
  const marker = new RegExp(`<h2[^>]*>${heading}</h2>`);
  if (!marker.test(post.html)) throw new Error(`Missing inbound-link section for ${post.slug}`);
  return {...post,html:post.html.replace(marker,match=>content+match),modified:'2026-10-13'};
}
